package dev.packsmith.mt; import bin.mt.plugin.api.editor.TextEditor; import bin.mt.plugin.api.ui.PluginUI; public class LinkRpFromClipboardMenu extends CompatMenuBase { public String name(){return "Add RP dependency from clipboard";} public void onMenuClick(PluginUI ui,TextEditor e){CharSequence clip=ctx().getClipboardText();String u=clip==null?null:clip.toString();if(u==null||!u.matches("[0-9a-fA-F-]{36}")){ui.showToast("Clipboard is not a UUID");return;}EditorUtil.replaceSelectionOrAll(e,ManifestUtil.linkDependency(EditorUtil.selectedOrAll(e),u,PackSettings.version(ctx())));ui.showToast("Dependency added");}}